<?php
/**
 * apply_leads_fix_patch.php
 *
 * Ships the /leads fixes from the 2026-09-13 audit: six cross-tenant data
 * leaks, four 500 errors, four silently wrong behaviours and the export/page
 * N+1 queries.
 *
 * Run from the Laravel root (or anywhere below it):
 *
 *   php apply_leads_fix_patch.php             dry run - checks only, writes nothing
 *   php apply_leads_fix_patch.php --apply     apply the fix
 *   php apply_leads_fix_patch.php --rollback  restore from the newest backup
 *
 * Why whole files and not anchors: the LeadController changes are large and
 * interlocking (the controller and the export both depend on the new
 * app/Services/LeadScope.php), so a partial apply is itself a 500. So the
 * script works all-or-nothing, and never leaves the site half-patched:
 *
 * - A file is replaced ONLY when the server copy still hashes to the version
 *   this fix was built on (production manifest, 2026-09-12). A file changed on
 *   the server since is never overwritten. Hashes ignore CRLF/LF differences.
 * - The dry run also checks that every target file AND its directory are
 *   writable by the user running the script, so a permission problem is
 *   reported before anything happens, not halfway through.
 * - All files are checked BEFORE any is written. One problem = zero writes.
 * - Takes its own backup first, to storage/backups/leads-fix-<timestamp>/, and
 *   hash-verifies it. No manual backup step is needed.
 * - Every write is verified. After writing, a separate PHP process loads each
 *   changed class through Composer's autoloader. If any write or that load
 *   fails, every file already written is put back automatically.
 * - Idempotent: a file that already has the fixed content is skipped.
 * - --rollback restores from the newest backup, but only files that still hold
 *   exactly what this patch wrote - a file edited after the patch is kept.
 *
 * Exit codes: 0 ok, 1 setup error, 2 blocked by the checks (nothing written),
 * 3 backup failed (nothing written), 4 a write failed (undone),
 * 5 autoload check failed (undone), 6 undo incomplete - run --rollback.
 */

$root = __DIR__;
while (!file_exists($root . '/artisan') && dirname($root) !== $root) {
    $root = dirname($root);
}
if (!file_exists($root . '/artisan')) {
    fwrite(STDERR, "Could not locate the Laravel root (no artisan found).\n");
    exit(1);
}

$mode = 'check';
if (in_array('--apply', $argv, true)) {
    $mode = 'apply';
} elseif (in_array('--rollback', $argv, true)) {
    $mode = 'rollback';
}

// Test hook only: make the write of one file fail on purpose, to prove the
// automatic undo works. Never needed in normal use.
$simulateWriteFailure = null;
foreach ($argv as $arg) {
    if (strpos($arg, '--simulate-write-failure=') === 0) {
        $simulateWriteFailure = substr($arg, strlen('--simulate-write-failure='));
    }
}

const BACKUP_PREFIX = 'leads-fix-';

$files = array (
  0 => 
  array (
    'path' => 'app/Http/Controllers/LeadController.php',
    'kind' => 'modify',
    'expect' => '734a759a5e000d77',
    'new_hash' => '634ab9e207dbb506',
    'b64' => '',
  ),
  1 => 
  array (
    'path' => 'app/Services/LeadScope.php',
    'kind' => 'modify',
    'expect' => '92629ad9f6895a1d',
    'new_hash' => 'a746fac67cb60a19',
    'b64' => '',
  ),
  2 => 
  array (
    'path' => 'resources/views/leads/list.blade.php',
    'kind' => 'modify',
    'expect' => '2b6163fb544af8b4',
    'new_hash' => '4be5418c09b1c633',
    'b64' => '',
  ),
);

function h16($contents)
{
    return substr(hash('sha256', str_replace("\r\n", "\n", $contents)), 0, 16);
}

function backupBase($root)
{
    return $root . '/storage/backups';
}

/** Newest backup folder this script made, or null. Names sort by timestamp. */
function latestBackup($root)
{
    $dirs = glob(backupBase($root) . '/' . BACKUP_PREFIX . '*', GLOB_ONLYDIR) ?: [];
    sort($dirs);
    return $dirs ? end($dirs) : null;
}

function currentUser()
{
    if (function_exists('posix_geteuid') && function_exists('posix_getpwuid')) {
        $u = @posix_getpwuid(posix_geteuid());
        if ($u) {
            return $u['name'];
        }
    }
    return get_current_user();
}

function ownerOf($path)
{
    if (function_exists('posix_getpwuid')) {
        $o = @posix_getpwuid(@fileowner($path));
        if ($o) {
            return $o['name'];
        }
    }
    return null;
}

/**
 * Whether this file can be written the way the apply step writes it: new
 * content goes to a temp file beside the target and is renamed over it, so the
 * DIRECTORY must be writable, not just the file.
 */
function writeProblem($path, $kind)
{
    if ($kind === 'modify' && !is_writable($path)) {
        $owner = ownerOf($path);
        return 'file is not writable by ' . currentUser() . ($owner ? " (owned by $owner)" : '');
    }

    // walk up to the nearest directory that exists - it is where mkdir would start
    $dir = dirname($path);
    while (!is_dir($dir)) {
        if (file_exists($dir)) {
            return "$dir exists but is not a directory";
        }
        $parent = dirname($dir);
        if ($parent === $dir) {
            break;
        }
        $dir = $parent;
    }

    if (!is_writable($dir)) {
        $owner = ownerOf($dir);
        return "directory $dir is not writable by " . currentUser() . ($owner ? " (owned by $owner)" : '');
    }

    return null;
}

function lintOk($contents, &$message)
{
    if (!function_exists('exec')) {
        $message = 'exec() disabled - lint skipped';
        return true;
    }
    $tmp = tempnam(sys_get_temp_dir(), 'leadsfix');
    file_put_contents($tmp, $contents);
    $out = [];
    $code = 0;
    exec(escapeshellarg(PHP_BINARY) . ' -l ' . escapeshellarg($tmp) . ' 2>&1', $out, $code);
    unlink($tmp);
    $message = trim(implode(' ', $out));
    return $code === 0;
}

function isPhpClassFile($path)
{
    return substr($path, 0, 4) === 'app/' && substr($path, -4) === '.php' && substr($path, -10) !== '.blade.php';
}

/**
 * Load every changed class in a separate PHP process, through the project's own
 * Composer autoloader. Catches exactly what went wrong on 2026-09-15: a class
 * the new code needs that the autoloader cannot find. Returns true/false, or
 * null when exec() is unavailable and the check could not run.
 */
function classesLoad($root, $plan, &$message)
{
    $classes = [];
    foreach ($plan as $f) {
        if (isPhpClassFile($f['path'])) {
            $classes[] = 'App\\' . str_replace('/', '\\', substr($f['path'], 4, -4));
        }
    }
    if (!$classes) {
        return true;
    }
    if (!function_exists('exec')) {
        $message = 'exec() disabled - autoload check skipped';
        return null;
    }

    $probe = tempnam(sys_get_temp_dir(), 'leadsfixprobe');
    file_put_contents(
        $probe,
        "<?php\n"
        . "require " . var_export($root . '/vendor/autoload.php', true) . ";\n"
        . "foreach (" . var_export($classes, true) . " as \$c) {\n"
        . "    if (!class_exists(\$c)) {\n"
        . "        echo \"cannot load \$c\\n\";\n"
        . "        exit(1);\n"
        . "    }\n"
        . "}\n"
        . "exit(0);\n"
    );

    $out = [];
    $code = 0;
    exec(escapeshellarg(PHP_BINARY) . ' ' . escapeshellarg($probe) . ' 2>&1', $out, $code);
    unlink($probe);

    $message = trim(implode(' ', $out));
    return $code === 0;
}

/**
 * Put back every file this run touched: modified files from the backup,
 * created files removed. Returns true when the tree is verifiably back to its
 * pre-run state.
 */
function undoWrites($root, $touched, $backup)
{
    echo "\nPutting back the files this run touched...\n";
    $clean = true;

    foreach (array_reverse($touched) as $f) {
        $path = $root . '/' . $f['path'];
        @unlink($path . '.tmp-leads-fix');

        if ($f['kind'] === 'create') {
            if (is_file($path)) {
                @unlink($path);
            }
            $ok = !file_exists($path);
            echo ($ok ? '       removed  ' : '  !!!  could not remove ') . $f['path'] . "\n";
        } else {
            $current = is_file($path) ? h16(file_get_contents($path)) : null;
            if ($current !== $f['expect']) {
                @copy($backup . '/' . $f['path'], $path);
            }
            $ok = is_file($path) && h16(file_get_contents($path)) === $f['expect'];
            echo ($ok ? '       restored ' : '  !!!  could not restore ') . $f['path'] . "\n";
        }

        $clean = $clean && $ok;
    }

    return $clean;
}

echo "apply_leads_fix v4  (country list, sales-only users filter, list USERS column) - requires v3 on the server\n\n";
echo "Laravel root: $root\n";
echo "Running as:   " . currentUser() . "\n";
echo "Mode:         $mode\n\n";

/* ------------------------------------------------------------------ *
 * rollback                                                           *
 * ------------------------------------------------------------------ */
if ($mode === 'rollback') {
    $backup = latestBackup($root);
    if (!$backup) {
        echo "No backup found under storage/backups/ - nothing to roll back.\n";
        exit(1);
    }
    echo "Restoring from: $backup\n\n";

    $restored = 0;
    $kept = 0;
    foreach ($files as $f) {
        $path = $root . '/' . $f['path'];
        $current = is_file($path) ? h16(file_get_contents($path)) : null;

        if ($f['kind'] === 'modify') {
            $saved = $backup . '/' . $f['path'];
            if (!is_file($saved)) {
                echo "[SKIP] {$f['path']} -- not in this backup\n";
                continue;
            }
            // Only undo our own write. A file edited after the patch is kept.
            if ($current !== $f['new_hash']) {
                echo "[KEEP] {$f['path']} -- changed since the patch, not overwriting\n";
                $kept++;
                continue;
            }
            copy($saved, $path);
            echo "[ OK ] {$f['path']} -- restored\n";
            $restored++;
            continue;
        }

        // created files: remove only if still exactly what this patch wrote
        if ($current === null) {
            echo "[SKIP] {$f['path']} -- not present\n";
            continue;
        }
        if ($current !== $f['new_hash']) {
            echo "[KEEP] {$f['path']} -- changed since the patch, not deleting\n";
            $kept++;
            continue;
        }
        unlink($path);
        echo "[ OK ] {$f['path']} -- removed\n";
        $restored++;
    }

    echo "\nrestored: $restored   kept: $kept\n";
    if ($kept > 0) {
        echo "Files marked KEEP were edited after the patch. Their pre-patch copies\n";
        echo "are still in $backup if you want them.\n";
    }
    echo "Next: php artisan view:clear && php artisan optimize:clear\n";
    exit($kept > 0 ? 2 : 0);
}

/* ------------------------------------------------------------------ *
 * check every file first - nothing is written in this pass           *
 * ------------------------------------------------------------------ */
$plan = [];
$blocked = 0;

foreach ($files as $f) {
    $path = $root . '/' . $f['path'];
    $new = base64_decode($f['b64']);

    if (h16($new) !== $f['new_hash']) {
        echo "[FAIL] {$f['path']} -- embedded content is corrupt\n";
        $blocked++;
        continue;
    }

    $exists = is_file($path);
    $current = $exists ? h16(file_get_contents($path)) : null;

    if ($current === $f['new_hash']) {
        echo "[SKIP] {$f['path']} -- already applied\n";
        continue;
    }

    if ($f['kind'] === 'create') {
        if ($exists) {
            echo "[FAIL] {$f['path']} -- already exists with different content ($current)\n";
            $blocked++;
            continue;
        }
    } else {
        if (!$exists) {
            echo "[FAIL] {$f['path']} -- file not found\n";
            $blocked++;
            continue;
        }
        if ($current !== $f['expect']) {
            echo "[FAIL] {$f['path']} -- production copy changed since 2026-09-12\n";
            echo "       expected {$f['expect']}, found $current\n";
            $blocked++;
            continue;
        }
    }

    $problem = writeProblem($path, $f['kind']);
    if ($problem !== null) {
        echo "[FAIL] {$f['path']} -- $problem\n";
        $blocked++;
        continue;
    }

    if (isPhpClassFile($f['path'])) {
        $lint = '';
        if (!lintOk($new, $lint)) {
            echo "[FAIL] {$f['path']} -- new content does not lint: $lint\n";
            $blocked++;
            continue;
        }
    }

    echo "[READY] {$f['path']} -- " . ($f['kind'] === 'create' ? 'will be created' : 'matches baseline, will be replaced') . "\n";
    $plan[] = $f;
}

$backupProblem = null;
if (!empty($plan)) {
    // Same walk-up check the backup step's mkdir will face: the nearest existing
    // ancestor of storage/backups must be a writable directory.
    $problem = writeProblem(backupBase($root) . '/probe', 'create');
    if ($problem !== null) {
        $backupProblem = 'backup location ' . backupBase($root) . ": $problem";
    }
}

echo "\n--------------------------------------------------\n";
echo "ready: " . count($plan) . "   blocked: $blocked\n";
if ($backupProblem) {
    echo "backup: $backupProblem\n";
}

if ($blocked > 0 || $backupProblem) {
    echo "\nNOTHING WAS WRITTEN. Fix the problems above and re-run. A file that\n";
    echo "changed on the server must be sent back so the fix can be re-merged.\n";
    exit($blocked > 0 ? 2 : 3);
}

if (empty($plan)) {
    echo "\nEverything is already applied.\n";
    exit(0);
}

if ($mode === 'check') {
    echo "\nDry run only. Re-run with --apply to write these files.\n";
    exit(0);
}

/* ------------------------------------------------------------------ *
 * apply                                                              *
 * ------------------------------------------------------------------ */
// New files first, so the controller never loads without LeadScope present.
usort($plan, function ($a, $b) {
    return ($a['kind'] === 'create' ? 0 : 1) <=> ($b['kind'] === 'create' ? 0 : 1);
});

// Backup pass. Any failure stops the run before an application file is touched.
$backup = backupBase($root) . '/' . BACKUP_PREFIX . date('Ymd-His');
if (is_dir($backup)) {
    $n = 2;
    while (is_dir($backup . '-' . $n)) {
        $n++;
    }
    $backup .= '-' . $n;
}

echo "Backing up to $backup\n";
$manifest = "leads-fix backup, " . date('Y-m-d H:i:s') . "\nsha256[0:16] (LF-normalised)  path\n";

foreach ($plan as $f) {
    if ($f['kind'] !== 'modify') {
        continue;
    }
    $src = $root . '/' . $f['path'];
    $dst = $backup . '/' . $f['path'];

    $ok = (is_dir(dirname($dst)) || @mkdir(dirname($dst), 0750, true))
        && @copy($src, $dst)
        && h16(file_get_contents($dst)) === $f['expect'];

    if (!$ok) {
        echo "[FAIL] could not back up {$f['path']} to $dst\n";
        echo "\nNOTHING WAS WRITTEN. Check that storage/ is writable, then re-run.\n";
        exit(3);
    }
    $manifest .= $f['expect'] . "  " . $f['path'] . "\n";
    echo "       saved {$f['path']}\n";
}

// storage/ is normally outside the web root; deny it anyway in case it is not.
@file_put_contents($backup . '/.htaccess', "<IfModule mod_authz_core.c>\n    Require all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\n    Deny from all\n</IfModule>\n");
@file_put_contents($backup . '/MANIFEST.txt', $manifest);
echo "       backup verified\n\n";

// Write pass. Every step is checked; the first failure undoes everything.
$touched = [];
foreach ($plan as $f) {
    $path = $root . '/' . $f['path'];
    $dir = dirname($path);
    $tmp = $path . '.tmp-leads-fix';
    $touched[] = $f;

    $step = 'create directory';
    $ok = is_dir($dir) || @mkdir($dir, 0755, true);

    if ($ok && $simulateWriteFailure === $f['path']) {
        $step = 'write (simulated failure)';
        $ok = false;
    }
    if ($ok) {
        $step = 'write temp file';
        $ok = @file_put_contents($tmp, base64_decode($f['b64'])) !== false;
    }
    if ($ok && $f['kind'] === 'modify') {
        @chmod($tmp, fileperms($path) & 0777);
    }
    if ($ok) {
        $step = 'move into place';
        $ok = @rename($tmp, $path);
    }
    if ($ok) {
        $step = 'verify content';
        $ok = is_file($path) && h16(file_get_contents($path)) === $f['new_hash'];
    }

    if (!$ok) {
        $err = error_get_last();
        echo "[FAIL] {$f['path']} -- could not $step" . ($err ? ': ' . $err['message'] : '') . "\n";
        if (!undoWrites($root, $touched, $backup)) {
            echo "\nUNDO INCOMPLETE. Run: php " . basename(__FILE__) . " --rollback\n";
            exit(6);
        }
        echo "\nThe site is back exactly as it was before this run. Nothing kept.\n";
        exit(4);
    }

    echo "[ OK ] {$f['path']}\n";
}

// Load every changed class exactly the way Laravel will.
$loadMessage = '';
$loads = classesLoad($root, $plan, $loadMessage);
if ($loads === false) {
    echo "\n[FAIL] autoload check -- $loadMessage\n";
    if (!undoWrites($root, $touched, $backup)) {
        echo "\nUNDO INCOMPLETE. Run: php " . basename(__FILE__) . " --rollback\n";
        exit(6);
    }
    echo "\nThe site is back exactly as it was before this run. Nothing kept.\n";
    echo "If a new class is not found, try: composer dump-autoload -o   then re-run.\n";
    exit(5);
}
echo $loads === null ? "\n[WARN] $loadMessage\n" : "\n[ OK ] every changed class loads through the autoloader\n";

echo "\nApplied " . count($plan) . " files.\n";
echo "Next:\n";
echo "  php artisan view:clear\n";
echo "  php artisan optimize:clear\n";
echo "Then open /leads, /leads/list, one lead, and the export.\n";
echo "To undo: php " . basename(__FILE__) . " --rollback\n";
exit(0);
